# Python Sidecar Engine with Health Monitoring

Here's a robust Python script using FastAPI that acts as a local sidecar engine with health monitoring and graceful shutdown:

```python
import asyncio
import signal
import sys
import threading
import time
from queue import Queue
from typing import Optional

import uvicorn
from fastapi import FastAPI, HTTPException
from fastapi.responses import JSONResponse
from fastapi.middleware.cors import CORSMiddleware
import psutil
import gc
import os

# Create FastAPI app
app = FastAPI(title="Sidecar Engine", description="Local sidecar with health monitoring")

# Add CORS middleware (optional, remove if not needed)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Thread-safe queue for background worker
task_queue = Queue()
worker_thread = None
worker_lock = threading.Lock()

# Health monitoring state
health_state = {
    "timestamp": None,
    "ram_usage_percent": 0.0,
    "ram_total_mb": 0,
    "ram_available_mb": 0,
    "vram_usage_percent": 0.0,
    "vram_total_mb": 0,
    "vram_available_mb": 0,
    "cpu_percent": 0.0,
    "active_workers": 0,
    "is_running": True
}

# Global shutdown flag
shutdown_requested = False

def get_system_health():
    """Get current system health metrics"""
    try:
        # Get RAM usage
        process = psutil.Process(os.getpid())
        ram_info = psutil.virtual_memory()
        ram_total_mb = ram_info.total // (1024 * 1024)
        ram_available_mb = ram_info.available // (1024 * 1024)
        ram_usage_percent = ram_info.percent

        # Get VRAM usage (if available)
        vram_usage_percent = 0.0
        vram_total_mb = 0
        vram_available_mb = 0

        # Try to get GPU memory info (fallback to 0 if not available)
        try:
            import GPUtil
            gpus = GPUtil.getGPUs()
            if gpus:
                gpu = gpus[0]
                vram_usage_percent = gpu.memoryUsed / gpu.memoryTotal * 100
                vram_total_mb = gpu.memoryTotal
                vram_available_mb = gpu.memoryFree
        except ImportError:
            pass  # No GPUtil, fallback to 0
        except Exception:
            pass  # Any error, fallback to 0

        # Get CPU usage
        cpu_percent = psutil.cpu_percent(interval=0.1)

        # Update health state
        health_state.update({
            "timestamp": time.time(),
            "ram_usage_percent": ram_usage_percent,
            "ram_total_mb": ram_total_mb,
            "ram_available_mb": ram_available_mb,
            "vram_usage_percent": vram_usage_percent,
            "vram_total_mb": vram_total_mb,
            "vram_available_mb": vram_available_mb,
            "cpu_percent": cpu_percent,
            "active_workers": 0,  # Will be updated by worker thread
            "is_running": True
        })

        return health_state

    except Exception as e:
        print(f"Error getting system health: {e}")
        return health_state

def background_worker():
    """Background worker that processes tasks from the queue"""
    while not shutdown_requested:
        try:
            # Check if we should exit
            if shutdown_requested:
                break

            # Try to get a task from the queue
            task = task_queue.get_nowait()

            # Process the task (placeholder - implement your logic here)
            try:
                # Simulate work
                time.sleep(0.1)
                # Your actual work here
                # result = process_task(task)
                # print(f"Processed task: {task}")

            except Exception as e:
                print(f"Error processing task: {e}")
                continue

            # Mark task as done
            task_queue.task_done()

        except queue.Empty:
            # No tasks available, sleep briefly
            time.sleep(0.1)
        except Exception as e:
            print(f"Error in background worker: {e}")
            time.sleep(0.1)

    # Cleanup when worker exits
    print("Background worker shutting down...")

def start_worker_thread():
    """Start the background worker thread"""
    global worker_thread
    with worker_lock:
        if worker_thread is None:
            worker_thread = threading.Thread(target=background_worker, daemon=True)
            worker_thread.start()
            print("Background worker started")

def health_check():
    """Update health state and return current state"""
    current_health = get_system_health()
    return current_health

@app.get("/api/health", response_model=dict)
async def health():
    """Health endpoint that reports active hardware state"""
    health_state = health_check()
    return health_state

@app.get("/api/status")
async def status():
    """Status endpoint for monitoring"""
    health_state = health_check()
    return {
        "status": "running",
        "health_state": health_state
    }

@app.get("/api/queue-size")
async def queue_size():
    """Endpoint to check queue size"""
    return {"queue_size": task_queue.qsize()}

@app.post("/api/queue")
async def add_to_queue(task: dict):
    """Endpoint to add a task to the queue"""
    try:
        task_queue.put(task)
        return {"status": "task added", "queue_size": task_queue.qsize()}
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to add task: {e}")

def signal_handler(signum, frame):
    """Handle graceful shutdown on SIGINT/SIGTERM"""
    global shutdown_requested
    shutdown_requested = True
    print(f"\nReceived signal {signum}. Shutting down gracefully...")

    # Gracefully shutdown the worker thread
    if worker_thread and worker_thread.is_alive():
        # Try to interrupt the worker thread
        worker_thread.join(timeout=2.0)
        if worker_thread.is_alive():
            print("Worker thread did not terminate gracefully, force killing...")
            worker_thread.join()

    # Shutdown FastAPI server
    print("Shutting down FastAPI server...")
    try:
        # Wait for server to shutdown gracefully
        uvicorn_server = getattr(app, "_server", None)
        if uvicorn_server:
            uvicorn_server.shutdown()
        else:
            # If running without uvicorn, we need to handle it differently
            # This is a fallback for cases where server isn't properly initialized
            print("FastAPI server shutdown complete")
    except Exception as e:
        print(f"Error during server shutdown: {e}")

    print("Sidecar engine shutdown complete")

def main():
    """Main function to start the server"""
    # Set up signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Start background worker
    start_worker_thread()

    # Create FastAPI server
    config = uvicorn.Config(
        app,
        host="0.0.0.0",
        port=8080,
        log_level="info",
        loop="asyncio"
    )

    server = uvicorn.Server(config)

    print("Starting Sidecar Engine...")
    print("Health endpoint: http://localhost:8080/api/health")
    print("Queue endpoint: http://localhost:8080/api/queue")
    print("Status endpoint: http://localhost:8080/api/status")

    try:
        # Start server
        server.run()
    except KeyboardInterrupt:
        print("\nReceived SIGINT, shutting down...")
        signal_handler(signal.SIGINT, None)
    except Exception as e:
        print(f"Error starting server: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

