use std::process::{Command, Stdio};
use std::time::Duration;
use std::thread;
use std::sync::Arc;
use std::sync::Mutex;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::Instant;

#[derive(Debug)]
pub struct SidecarManager {
    sidecar_process: Option<Child>,
    is_running: Arc<AtomicBool>,
    health_url: String,
}

impl SidecarManager {
    pub fn new(health_url: String) -> Self {
        Self {
            sidecar_process: None,
            is_running: Arc::new(AtomicBool::new(false)),
            health_url,
        }
    }

    pub fn start(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        // Start the sidecar process
        let mut child = Command::new("python3")
            .arg("sidecar_engine.py")  // Adjust path if needed
            .stdout(Stdio::inherit())
            .stderr(Stdio::inherit())
            .spawn()?;

        self.sidecar_process = Some(child);
        self.is_running.store(true, Ordering::SeqCst);

        println!("Sidecar process started with PID: {}", child.id());

        Ok(())
    }

    pub fn is_running(&self) -> bool {
        self.is_running.load(Ordering::SeqCst)
    }

    pub fn health_check(&self) -> Result<SidecarHealth, Box<dyn std::error::Error>> {
        let url = format!("http://localhost:8080{}", self.health_url);

        let response = reqwest::blocking::get(&url)?;
        if !response.status().is_success() {
            return Err(format!("HTTP error: {}", response.status()).into());
        }

        let health: SidecarHealth = response.json()?;
        Ok(health)
    }

    pub fn poll_health(&self, timeout: Duration) -> Result<SidecarHealth, Box<dyn std::error::Error>> {
        let mut attempts = 0;
        let max_attempts = 10; // Maximum 10 attempts
        let mut backoff = Duration::from_millis(100);

        while attempts < max_attempts {
            match self.health_check() {
                Ok(health) => {
                    println!("Health check successful after {} attempts", attempts + 1);
                    return Ok(health);
                }
                Err(e) => {
                    attempts += 1;
                    println!("Health check failed (attempt {}): {}", attempts, e);

                    // Exponential backoff
                    thread::sleep(backoff);
                    backoff *= 2; // Double the backoff time

                    // Check if we've exceeded timeout
                    if attempts >= max_attempts {
                        return Err(format!("Health check timeout after {} attempts", max_attempts).into());
                    }
                }
            }
        }

        Err(format!("Health check failed after {} attempts", max_attempts).into())
    }

    pub fn stop(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        if let Some(ref mut child) = self.sidecar_process {
            if child.try_wait().is_err() {
                // Process is still running
                child.kill()?;
                println!("Sent SIGTERM to sidecar process");

                // Wait for process to terminate
                let start = Instant::now();
                while start.elapsed() < Duration::from_secs(5) {
                    if child.try_wait().is_ok() {
                        println!("Sidecar process terminated");
                        break;
                    }
                    thread::sleep(Duration::from_millis(100));
                }
            }
        }

        self.is_running.store(false, Ordering::SeqCst);
        Ok(())
    }
}

