const axios = require('axios');
const { spawn } = require('child_process');
const { setTimeout } = require('timers');
const EventEmitter = require('events');

class SidecarManager extends EventEmitter {
    constructor(healthUrl = '/api/health', sidecarPath = './sidecar_engine.py') {
        super();
        this.healthUrl = healthUrl;
        this.sidecarPath = sidecarPath;
        this.sidecarProcess = null;
        this.isRunning = false;
        this.healthPolling = null;
        this.healthCheckTimeout = 10000; // 10 seconds
        this.maxRetries = 10;
        this.backoffFactor = 100; // milliseconds
    }

    async start() {
        try {
            // Start the sidecar process
            this.sidecarProcess = spawn('python3', [this.sidecarPath], {
                stdio: 'inherit',
                detached: true
            });

            // Wait for process to start
            await new Promise(resolve => {
                setTimeout(resolve, 1000);
            });

            this.isRunning = true;
            this.emit('started');

            console.log('Sidecar process started with PID:', this.sidecarProcess.pid);
            return true;
        } catch (error) {
            console.error('Failed to start sidecar:', error);
            this.emit('error', error);
            return false;
        }
    }

    async healthCheck() {
        try {
            const response = await axios.get(`http://localhost:8080${this.healthUrl}`);
            return response.data;
        } catch (error) {
            throw new Error(`Health check failed: ${error.message}`);
        }
    }

    async pollHealth(timeout = 10000) {
        let attempts = 0;
        let backoff = this.backoffFactor;

        while (attempts < this.maxRetries) {
            try {
                const health = await this.healthCheck();
                console.log(`Health check successful after ${attempts + 1} attempts`);
                return health;
            } catch (error) {
                attempts++;
                console.log(`Health check failed (attempt ${attempts}): ${error.message}`);

                // Exponential backoff
                await new Promise(resolve => setTimeout(resolve, backoff));
                backoff *= 2;

                // Check if we've exceeded timeout
                if (attempts >= this.maxRetries) {
                    throw new Error(`Health check timeout after ${this.maxRetries} attempts`);
                }
            }
        }

        throw new Error(`Health check failed after ${this.maxRetries} attempts`);
    }

    async stop() {
        if (!this.isRunning) {
            return true;
        }

        try {
            if (this.sidecarProcess) {
                this.sidecarProcess.kill('SIGTERM');
                this.sidecarProcess = null;
                console.log('Sent SIGTERM to sidecar process');

                // Wait for process to terminate
                const start = Date.now();
                while (Date.now() - start < 5000) {
                    if (this.sidecarProcess && this.sidecarProcess.killed) {
                        console.log('Sidecar process terminated');
                        break;
                    }
                    await new Promise(resolve => setTimeout(resolve, 100));
                }
            }

            this.isRunning = false;
            this.emit('stopped');
            return true;
        } catch (error) {
            console.error('Failed to stop sidecar:', error);
            this.emit('error', error);
            return false;
        }
    }

    async startAndPoll(timeout = 10000) {
        // Start sidecar if not already running
        if (!this.isRunning) {
            await this.start();
        }

        // Poll health
        try {
            const health = await this.pollHealth(timeout);
            return health;
        } catch (error) {
            console.error('Failed to poll health:', error);
            throw error;
        }
    }
}

// Export for use in other modules
module.exports = SidecarManager;

