    try {
        // Start sidecar
        await manager.start();

        // Poll health with exponential backoff
        const health = await manager.pollHealth(10000);
        console.log('Health check successful:', health);

        // Stop sidecar after 5 seconds
        setTimeout(async () => {
            await manager.stop();
            console.log('Sidecar stopped');
        }, 5000);
    } catch (error) {
        console.error('Error:', error);
    }
}

// Run main function
main().catch(console.error);
